refentry.refsect1:
&reftitle.description;
boolstream_filter_register stringfilter_name stringclass
stream_filter_register allows you to implement your own filter on any registered stream used with all the other filesystem functions (such as fopen, fread etc.).

&reftitle.returnvalues;
&return.success;
stream_filter_register will return &false; if the filter_name is already defined, including when it collides with a built-in filter such as string.rot13, convert.*, zlib.*, dechunk or consumed. A name such as string.* or STRING.ROT13 does not collide and is accepted.

&reftitle.errors;

 Throws a ValueError if
 filter_name or class is empty.

&reftitle.changelog;





    &Version;
    &Description;





    8.0.0

     Now throws a ValueError if
     filter_name or class
     is empty.
     Previously, an E_WARNING was raised and &false; was returned.

  &reftitle.examples;



    Filter for capitalizing characters on foo-bar.txt stream


     The example below implements a filter named strtoupper
     on the foo-bar.txt stream which will capitalize
     all letter characters written to/read from that stream.



<?php

/* Define our filter class */
class strtoupper_filter extends php_user_filter {
  function filter($in, $out, &$consumed, bool $closing): int
  {
    while ($bucket = stream_bucket_make_writeable($in)) {
      $bucket->data = strtoupper($bucket->data);
      $consumed += $bucket->datalen;
      stream_bucket_append($out, $bucket);
    }
    return PSFS_PASS_ON;
  }
}

/* Register our filter with PHP */
stream_filter_register("strtoupper", "strtoupper_filter")
    or die("Failed to register filter");

$fp = fopen("foo-bar.txt", "w");

/* Attach the registered filter to the stream just opened */
stream_filter_append($fp, "strtoupper");

fwrite($fp, "Line1\n");
fwrite($fp, "Word - 2\n");
fwrite($fp, "Easy As 123\n");

fclose($fp);

/* Read the contents back out
 */
readfile("foo-bar.txt");


    &example.outputs;


LINE1
WORD - 2
EASY AS 123







    Registering a generic filter class to match multiple filter names.


<?php

/* Define our filter class */
class string_filter extends php_user_filter {
  var $mode;

  function filter($in, $out, &$consumed, bool $closing): int
  {
    while ($bucket = stream_bucket_make_writeable($in)) {
      if ($this->mode == 1) {
        $bucket->data = strtoupper($bucket->data);
      } elseif ($this->mode == 0) {
        $bucket->data = strtolower($bucket->data);
      }

      $consumed += $bucket->datalen;
      stream_bucket_append($out, $bucket);
    }
    return PSFS_PASS_ON;
  }

  function onCreate(): bool
  {
    if ($this->filtername == 'str.toupper') {
      $this->mode = 1;
    } elseif ($this->filtername == 'str.tolower') {
      $this->mode = 0;
    } else {
      /* Some other str.* filter was asked for,
         report failure: the filter cannot be created */
      return false;
    }

    return true;
  }
}

/* Register our filter with PHP */
stream_filter_register("str.*", "string_filter")
    or die("Failed to register filter");

$fp = fopen("foo-bar.txt", "w");

/* Attach the registered filter to the stream just opened
   We could alternately bind to str.tolower here */
stream_filter_append($fp, "str.toupper");

fwrite($fp, "Line1\n");
fwrite($fp, "Word - 2\n");
fwrite($fp, "Easy As 123\n");

fclose($fp);

/* Read the contents back out
 */
readfile("foo-bar.txt");


    &example.outputs;


LINE1
WORD - 2
EASY AS 123
